const VERSION='anatomy-v15.2';
self.addEventListener('install',e=>{e.waitUntil((async()=>{const manifest=await fetch('./offline-assets.json').then(r=>r.json());const cache=await caches.open(VERSION+'-core');await cache.addAll(manifest.core);await self.skipWaiting();})());});
self.addEventListener('activate',e=>e.waitUntil((async()=>{const names=await caches.keys();const core=await caches.open(VERSION+'-core');const manifest=await (await core.match('./offline-assets.json')).json();
// The Existing model binaries are unchanged. The new supplementary file downloads separately.
for(const previous of ['anatomy-v15.1','anatomy-v15','anatomy-v14.1','anatomy-v14','anatomy-v13.2','anatomy-v13.1','anatomy-v13','anatomy-v12.1','anatomy-v12','anatomy-v11','anatomy-v10','anatomy-v9','anatomy-v8','anatomy-v7','anatomy-v6'])for(const sex of ['male','female','volume'])if(names.includes(previous+'-'+sex)){const old=await caches.open(previous+'-'+sex),next=await caches.open(VERSION+'-'+sex);for(const url of manifest[sex]){const hit=await old.match(url)||(url.endsWith("thorax-male.rgb.bin")?await old.match("./volume/thorax-male.rgb.gz"):null);if(hit&&!await next.match(url))await next.put(url,hit);}}
for(const key of names)if(key.startsWith('anatomy-')&&!key.startsWith(VERSION))await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin)return;e.respondWith((async()=>{const local=['127.0.0.1','localhost'].includes(url.hostname),mutable=e.request.mode==='navigate'||/\.(?:js|css|html|json|webmanifest)$/.test(url.pathname);if(local&&mutable){try{const fresh=await fetch(e.request);if(fresh.ok)return fresh;}catch{}}const hit=await caches.match(e.request,{ignoreSearch:true});if(hit)return hit;try{return await fetch(e.request);}catch(err){if(e.request.mode==='navigate'){const cache=await caches.open(VERSION+'-core');const page=await cache.match('./index.html');if(page)return page;}throw err;}})());});
self.addEventListener('message',e=>{if(e.data?.type!=='download')return;const port=e.ports[0];e.waitUntil((async()=>{try{if(!['male','female','volume'].includes(e.data.sex))throw Error('Geçersiz model');const core=await caches.open(VERSION+'-core');const manifest=await (await core.match('./offline-assets.json')||await fetch('./offline-assets.json')).json();const files=manifest[e.data.sex];const cache=await caches.open(VERSION+'-'+e.data.sex);let done=0;for(const url of files){if(!await cache.match(url)){const response=await fetch(url);if(!response.ok)throw Error('Model dosyası indirilemedi');await cache.put(url,response);}port.postMessage({type:'progress',done:++done,total:files.length});}port.postMessage({type:'done',sex:e.data.sex});}catch(err){port.postMessage({type:'error',message:err.message});}})());});
